mapper.select:
select
sum(t.share_amt)
from TRD_PRODUCT_DEAL t
where t.finprod_id = #{finprodId,jdbcType=VARCHAR}

	and t.trade_date >= STR_TO_DATE(#{netValueDate,jdbcType=VARCHAR}, '%Y-%m-%d')


	and t.trade_date >= STR_TO_DATE(#{dealDate,jdbcType=VARCHAR}, '%Y-%m-%d')

and t.PS IN('C4')

	AND t.TRADE_STATUS = #{tradeStatus,jdbcType=VARCHAR}


	AND t.IS_CANCEL = #{isCancel,jdbcType=VARCHAR}

select crule.pay_cycle payCycle,
crule.pay_type payType,
min(cplan.mdate) mdate
from fin_cash_info cinfo
inner join fin_cash_pay_rule crule on cinfo.cash_id = crule.cash_id
left join fin_cash_plan cplan on cplan.cash_id = crule.cash_id
left join (
select max(trade_date) trade_date,#{finprodId,jdbcType=VARCHAR} finprod_id
from trd_fin_product_deal_total f
where finprod_id = #{finprodId,jdbcType=VARCHAR}
and PS IN (#{PS_C9}, #{PS_C10})
and TRADE_STATUS= #{TRADE_STATUS01}
and IS_CANCEL = #{YES_OR_NO_N}
) f on f.finprod_id = cinfo.finprod_id
left join (
select DISTINCT finprod_id,trade_date,settle_date
from trd_fin_product_deal_total
where finprod_id = #{finprodId,jdbcType=VARCHAR}
and PS IN (#{PS_C9}, #{PS_C10})
and TRADE_STATUS= #{TRADE_STATUS01}
and IS_CANCEL = #{YES_OR_NO_N}
) tot on tot.finprod_id = f.finprod_id
and tot.trade_date = f.trade_date
where cinfo.finprod_id = #{finprodId,jdbcType=VARCHAR}
and cinfo.cash_type_1 = #{cashType1,jdbcType=VARCHAR}
and cinfo.cash_type_2 = #{cashType2,jdbcType=VARCHAR}



	and ((cplan.mdate > IFNULL(f.trade_date,cplan.vdate) and  cplan.mdate  <=  STR_TO_DATE(#{PlatformDay,jdbcType=DATE},'%Y-%m-%d'))
	or(cplan.mdate =  IFNULL(f.trade_date,cplan.vdate) and tot.SETTLE_DATE = STR_TO_DATE(#{PlatformDay,jdbcType=DATE},'%Y-%m-%d'))
	or crule.pay_cycle in (#{payCycle07},#{payCycle08},#{payCycle09}))


	and ((cplan.mdate > IFNULL(f.trade_date,cplan.vdate) and  cplan.mdate  <=  STR_TO_DATE(#{PlatformDay,jdbcType=DATE},'%Y-%m-%d'))
	or(cplan.mdate =  IFNULL(f.trade_date,cplan.vdate) and tot.SETTLE_DATE = STR_TO_DATE(#{PlatformDay,jdbcType=DATE},'%Y-%m-%d'))
	or crule.pay_cycle in (#{payCycle07},#{payCycle08},#{payCycle09}))


group by crule.pay_cycle,crule.pay_type

select sum(FPRICE_AMT) from TRD_FIN_PRODUCT_DEAL_TOTAL where ps in (#{PS_09,jdbcType=VARCHAR},#{PS_10,jdbcType=VARCHAR})
AND FINPROD_ID  =  #{finprodId,jdbcType=VARCHAR}
and TRADE_DATE = STR_TO_DATE(#{netValueDate,jdbcType=VARCHAR}, '%Y-%m-%d')
AND TRADE_STATUS = #{TRADE_STATUS_01,jdbcType=VARCHAR}
AND IS_CANCEL = #{IS_CANCEL_N,jdbcType=VARCHAR}
